class Solution {
    public int trailingZeroes(int n) {
        int count = 0;
        for (int value = 1; value <= n; value++) {
            int remaining = value;
            while (remaining % 5 == 0) {
                count++;
                remaining /= 5;
            }
        }
        return count;
    }
}

